18	/**
19	 * Base class for running doctests as PHPUnit tests.
20	 *
21	 * Extend this class and implement the configure() method to run doctests
22	 * for your project. Each example found becomes one PHPUnit test case.
23	 *
24	 * This class binds its data provider with a PHPUnit attribute and therefore
25	 * needs PHPUnit 10 or later. On PHPUnit 9 extend
26	 * PhpAiToolkit\Doctest\TestCase\Legacy\LegacyDoctestRunner, which binds the
27	 * same provider with a doc-comment annotation.
28	 *
29	 * This is the only entry point the port carries. k-kinzal/doctest-php also
30	 * ships a DoctestCase wrapping one example, which nothing there uses and which
31	 * cannot work here: it names itself through the PHPUnit constructor, and
32	 * PHPUnit 10 made TestCase::__construct() final.
33	 */
34	abstract class DoctestRunner extends TestCase
35	{
36	    private static ?ExampleExecutor $executor = null;
37	
38	    /**
39	     * Override to provide custom configuration.
40	     *
41	     * @return Configuration the configuration for doctest scanning
42	     */
43	    abstract public static function configure(): Configuration;
44	
45	    /**
46	     * Provides examples as test data.
47	     *
48	     * @return iterable<string, array{Example}>
49	     */
50	    public static function doctestProvider(): iterable
51	    {
52	        $config = static::configure();
53	        $fileScanner = new FileScanner($config);
54	        $sourceScanner = new SourceScanner();
55	        $extractor = new ExampleExtractor();
56	
57	        foreach ($fileScanner->scan() as $filePath) {
58	            foreach ($sourceScanner->scanFile($filePath) as $target) {
59	                foreach ($extractor->extract($target) as $example) {
60	                    yield $example->getName() => [$example];
61	                }
62	            }
63	        }
64	    }
65	
66	    /**
67	     * Tests a docblock example.
68	     *
69	     * An example exercises whatever code it documents, so it declares no
70	     * coverage target of its own: it is a check on the documentation, not a
71	     * unit test of one class.
72	     *
73	     * @param Example $example the example to test
74	     */
75	    #[Test]
76	    #[DataProvider('doctestProvider')]
77	    #[CoversNothing]
78	    public function testDocblockExample(Example $example): void
79	    {
80	        if (self::$executor === null) {
81	            self::$executor = new ExampleExecutor(static::configure()->getBootstrap());
82	        }
83	
84	        $result = self::$executor->execute($example);
85	
86	        self::assertTrue($result->passed, $result->getErrorMessage());
87	    }
88	}
