 * Called by PHPUnit when the extension is loaded. The facade is the handle
 * an extension registers subscribers through; doctest registers none, and
 * takes nothing from it.
 *
 * @param PhpUnitConfiguration $configuration PHPUnit configuration
 * @param Facade $facade PHPUnit extension facade
 * @param ParameterCollection $parameters extension parameters from phpunit.xml
 */
public function bootstrap(
    PhpUnitConfiguration $configuration,
    Facade $facade,
    ParameterCollection $parameters,
): void {
    self::load($parameters, self::basePath($configuration));
}

/**
 * Stores the configuration the given parameters describe.
 *
 * A configuration that switches doctest off is not stored: the run keeps
 * whatever it already had, which is no configuration at all unless another
 * declaration supplied one.
 *
 * @param ParameterCollection $parameters extension parameters from phpunit.xml
 * @param string $basePath directory relative paths are resolved against
 */
public static function load(ParameterCollection $parameters, string $basePath): void
{
    $config = ConfigurationLoader::fromParameters($parameters, $basePath);
    if (!$config->isEnabled()) {
        return;
    }

    self::$configuration = $config;
}

