18	
19	use function preg_match;
20	
21	use RuntimeException;
22	
23	/**
24	 * Scans PHP source files to extract targets (classes, methods, functions) with docblocks.
25	 *
26	 * Uses PHP-Parser to analyze the AST (Abstract Syntax Tree) of source files
27	 * and extract all elements that have documentation blocks.
28	 *
29	 * The walk is written out here rather than delegated to a NodeVisitor, which is
30	 * how k-kinzal/doctest-php does it: the visitor interface signature differs
31	 * between the nikic/php-parser majors this package supports, while the node
32	 * accessors it uses do not.
33	 */
34	final class SourceScanner
35	{
36	    /** @readonly */
37	    private Parser $parser;
38	
39	    /**
40	     * Creates a scanner backed by a parser for the newest supported PHP version.
41	     *
42	     * @throws RuntimeException when no parser can be created
43	     */
44	    public function __construct(?ParserFactoryBridge $bridge = null)
45	    {
46	        $this->parser = ($bridge ?? new ParserFactoryBridge())->create();
47	    }
48	
49	    /**
50	     * Scans a PHP file and yields all targets with docblocks.
51	     *
52	     * Analyzes the file's AST to find file-level docblocks, classes, methods,
53	     * and functions that have documentation. A file that cannot be read or
54	     * parsed yields nothing.
55	     *
56	     * @param string $filePath absolute path to the PHP file
57	     * @return Generator<int, Target> targets found in the file
58	     */
59	    public function scanFile(string $filePath): Generator
60	    {
61	        $code = is_file($filePath) ? file_get_contents($filePath) : false;
62	        if ($code === false) {
63	            return;
64	        }
65	
66	        $errorHandler = new Collecting();
67	        $ast = $this->parser->parse($code, $errorHandler);
68	        if ($ast === null || $errorHandler->hasErrors()) {
69	            return;
70	        }
71	
72	        $fileDocblock = $this->extractFileDocblock($code);
73	        if ($fileDocblock !== null) {
74	            yield new Target(TargetKind::FILE, $filePath, $fileDocblock, basename($filePath), 1);
75	        }
76	
77	        yield from $this->traverseAst($ast, $filePath, null, null);
78	    }
79	
80	    /**
81	     * Returns the file-level docblock of the source, or null when it has none.
82	     *
83	     * Matches the first docblock that appears after the opening tag and before
84	     * any other code. An optional declare statement is skipped, which
85	     * k-kinzal/doctest-php does not do: PHP-CS-Fixer puts declare(strict_types=1)
86	     * directly after the opening tag, so a file-level docblock in a formatted
87	     * project always sits behind it.
88	     */
89	    public function extractFileDocblock(string $code): ?string
90	    {
91	        $matches = [];
92	        if (preg_match('/^<\?php\s*(?:declare\s*\([^)]*\)\s*;\s*)?(\/\*\*.*?\*\/)/s', $code, $matches) === 1) {
93	            return $matches[1];
94	        }
95	
96	        return null;
97	    }
98	
99	    /**
100	     * Yields every documented class, method, and function of the given nodes.
101	     *
102	     * @param array<mixed> $nodes
103	     * @return Generator<int, Target>
104	     */
105	    public function traverseAst(array $nodes, string $filePath, ?string $namespace, ?string $className): Generator
106	    {
107	        foreach ($nodes as $node) {
108	            if (!$node instanceof \PhpParser\Node) {
109	                continue;
110	            }
111	
112	            yield from $this->targetsOf($node, $filePath, $namespace, $className);
113	        }
114	    }
115	
116	    /**
117	     * Yields the targets one node contributes, then descends into it.
118	     *
119	     * @return Generator<int, Target>
120	     */
121	    public function targetsOf(\PhpParser\Node $node, string $filePath, ?string $namespace, ?string $className): Generator
122	    {
123	        if ($node instanceof \PhpParser\Node\Stmt\Namespace_) {
124	            yield from $this->traverseAst($node->stmts, $filePath, $node->name === null ? null : $node->name->toString(), null);
125	
126	            return;
127	        }
128	
129	        if ($node instanceof \PhpParser\Node\Stmt\Class_) {
130	            yield from $this->classTargets($node, $filePath, $namespace);
131	
132	            return;
133	        }
134	
135	        if ($node instanceof \PhpParser\Node\Stmt\ClassMethod) {
136	            yield from $this->methodTarget($node, $filePath, $namespace, $className);
137	
138	            return;
139	        }
140	
141	        if ($node instanceof \PhpParser\Node\Stmt\Function_) {
142	            yield from $this->functionTarget($node, $filePath, $namespace);
143	
144	            return;
145	        }
146	
147	        yield from $this->traverseAst($this->children($node), $filePath, $namespace, $className);
148	    }
149	
150	    /**
151	     * Yields the target of a documented class and then of its members.
152	     *
153	     * @return Generator<int, Target>
154	     */
155	    public function classTargets(\PhpParser\Node\Stmt\Class_ $node, string $filePath, ?string $namespace): Generator
156	    {
157	        $className = $node->name === null ? null : $node->name->toString();
158	        $docComment = $node->getDocComment();
159	        if ($docComment !== null && $className !== null) {
160	            yield new Target(TargetKind::CLASS_LIKE, $filePath, $docComment->getText(), $className, $docComment->getStartLine(), $namespace);
161	        }
162	
163	        yield from $this->traverseAst($node->stmts, $filePath, $namespace, $className);
164	    }
165	
166	    /**
167	     * Yields the target of a documented method declared inside a class.
168	     *
169	     * @return Generator<int, Target>
170	     */
171	    public function methodTarget(\PhpParser\Node\Stmt\ClassMethod $node, string $filePath, ?string $namespace, ?string $className): Generator
172	    {
173	        $docComment = $node->getDocComment();
174	        if ($docComment === null || $className === null) {
175	            return;
176	        }
177	
178	        yield new Target(
179	            TargetKind::METHOD,
180	            $filePath,
181	            $docComment->getText(),
182	            $node->name->toString(),
183	            $docComment->getStartLine(),
184	            $namespace,
185	            $className,
186	            $node->isStatic(),
187	        );
188	    }
189	
190	    /**
191	     * Yields the target of a documented function.
192	     *
193	     * @return Generator<int, Target>
194	     */
195	    public function functionTarget(\PhpParser\Node\Stmt\Function_ $node, string $filePath, ?string $namespace): Generator
196	    {
197	        $docComment = $node->getDocComment();
198	        if ($docComment === null) {
199	            return;
200	        }
201	
202	        yield new Target(TargetKind::FUNCTION, $filePath, $docComment->getText(), $node->name->toString(), $docComment->getStartLine(), $namespace);
203	    }
204	
205	    /**
206	     * Returns the direct sub-node values of one node.
207	     *
208	     * @return array<mixed>
209	     */
210	    public function children(\PhpParser\Node $node): array
211	    {
212	        $values = get_object_vars($node);
213	        $children = [];
214	        foreach ($node->getSubNodeNames() as $name) {
215	            $value = $values[$name] ?? null;
216	            if (is_array($value) || $value instanceof \PhpParser\Node) {
217	                $children[] = $value;
218	            }
219	        }
220	
221	        $flattened = [];
222	        foreach ($children as $child) {
223	            if (is_array($child)) {
224	                foreach ($child as $item) {
225	                    $flattened[] = $item;
226	                }
227	                continue;
228	            }
229	
230	            $flattened[] = $child;
231	        }
232	
233	        return $flattened;
234	    }
235	}
